</div></div><aside class="panel preview"><div class="panelhead"><div><h2>Попередній перегляд</h2><p>Зміни відображаються одразу</p></div></div><div class="screen"><div class="window"><div class="ptop">● IT Tasks Pro</div><div class="pcontent"><div class="pside"><i></i><i></i><i></i><i></i><i></i></div><div class="pbody"><h3>Мої завдання</h3><p>Навчайся та відстежуй прогрес</p><div class="pcards"><div class="pcard"><b>Python</b><small>Практика коду</small></div><div class="pcard"><b>HTML / CSS</b><small>Веброзробка</small></div></div><div class="answer">print("Hello, world!")</div></div></div></div></div><div class="previewnote">Демонстраційний макет. Фінальний вигляд також залежить від style.css.</div></aside></section></main></div>
<script>
(()=>{const cats=document.getElementById('categories'),work=document.getElementById('workspace'),title=document.getElementById('pagetitle'),desc=document.getElementById('pagedesc');const info={design:['Зовнішній вигляд','Теми, кольори та шрифти.'],interface:['Мова та інтерфейс','Мова та поведінка інтерфейсу.'],profile:['Профіль і безпека','Дані профілю та пароль.']};function openPage(n){cats.hidden=true;work.hidden=false;document.querySelectorAll('[data-page]').forEach(p=>{if(p.id!=='password-form')p.hidden=p.dataset.page!==n});document.getElementById('password-form').hidden=true;title.textContent=info[n][0];desc.textContent=info[n][1];window.scrollTo({top:0,behavior:'smooth'});}document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>openPage(b.dataset.open)));document.getElementById('back').addEventListener('click',()=>{work.hidden=true;cats.hidden=false;});const presets=<?=json_encode(array_map(fn($p)=>$p['colors'],$presets),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;function setColor(k,v){document.documentElement.style.setProperty('--'+k,v);document.querySelectorAll('[data-color-text="'+k+'"]').forEach(x=>x.textContent=v.toUpperCase());document.querySelectorAll('[data-color="'+k+'"]').forEach(x=>x.value=v)}document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('theme').value=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('selected',x===b));Object.entries(presets[b.dataset.theme]).forEach(([k,v])=>setColor(k,v));}));document.querySelectorAll('[data-color]').forEach(i=>i.addEventListener('input',()=>setColor(i.dataset.color,i.value)));const font=document.getElementById('font'),size=document.getElementById('size'),fontInterface=document.getElementById('font-interface'),sizeInterface=document.getElementById('size-interface');function applyFont(){if(font){document.documentElement.style.setProperty('--site-font',JSON.stringify(font.value));if(fontInterface)fontInterface.value=font.value}}function applySize(value){if(size){size.value=value;document.documentElement.style.setProperty('--site-font-size',value+'px');const sizeText=document.getElementById('size-text');if(sizeText)sizeText.textContent=value+' px'}if(sizeInterface)sizeInterface.value=value}if(font)font.addEventListener('change',applyFont);if(fontInterface)fontInterface.addEventListener('change',()=>{if(font)font.value=fontInterface.value;applyFont()});if(size)size.addEventListener('input',()=>applySize(size.value));if(sizeInterface)sizeInterface.addEventListener('change',()=>applySize(sizeInterface.value));document.getElementById('settings-form').addEventListener('submit',()=>{if(fontInterface&&font)fontInterface.value=font.value;if(sizeInterface&&size)sizeInterface.value=size.value});document.getElementById('show-password').addEventListener('click',()=>{document.querySelector('[data-page="profile"]').hidden=true;document.getElementById('password-form').hidden=false});document.getElementById('cancel-password').addEventListener('click',()=>{document.getElementById('password-form').hidden=true;document.querySelector('[data-page="profile"]').hidden=false});document.getElementById('password-form').addEventListener('submit',ev=>{const f=ev.currentTarget;if(f.new_password.value!==f.repeat_password.value){ev.preventDefault();alert('Нові паролі не збігаються.')}});})();
</script></body></html>
